import { z } from "zod";

// Maps the old app's media-library catalog.json to library rows. The old files carry their own licence text and source
// strings; the owner decided (2026-10-29) that every shipped clip gets the single licence below and source "shipped".

export const SHIPPED_LICENCE =
  "generated by the owner, redistributable (old README)";

const clip = z.object({
  id: z.string().min(1),
  file: z
    .string()
    .min(1)
    .refine(
      (f) => f.startsWith("clips/") && !f.includes("..") && !f.includes("\\"),
      "file must be inside clips/",
    ),
  category: z.string().min(1).optional(),
  function: z.string().min(1).optional(), // the four piano chords have this instead of a category
  desc: z.string().optional(),
  tags: z.array(z.string().min(1)).default([]),
  source: z.string().optional(),
  model: z.string().optional(),
  prompt: z.string().optional(),
});
const catalog = z.object({
  clips: z.array(
    clip.refine(
      (c) => c.category ?? c.function,
      "needs a category or function",
    ),
  ),
});

export interface CatalogEntry {
  kind: "sfx" | "music";
  name: string;
  file: string; // relative to the kind folder, e.g. clips/whoosh-soft.mp3
  tags: string[];
  source: "shipped";
  licence: string;
  provenance: Record<string, unknown>;
}

export function mapCatalog(
  kind: "sfx" | "music",
  json: unknown,
): CatalogEntry[] {
  return catalog.parse(json).clips.map((c) => {
    const category = (c.category ?? c.function)!;
    return {
      kind,
      name: c.id,
      file: c.file,
      tags: [...new Set([...c.tags, category])],
      source: "shipped",
      licence: SHIPPED_LICENCE,
      provenance: {
        catalogId: c.id,
        category,
        originalSource: c.source,
        model: c.model,
        prompt: c.prompt,
        desc: c.desc,
      },
    };
  });
}

/** Files found on disk that no catalog entry lists. */
export const unlistedFiles = (
  onDisk: string[],
  entries: CatalogEntry[],
): string[] => {
  const listed = new Set(entries.map((e) => e.file));
  return onDisk.filter((f) => !listed.has(f));
};
